const body = $input.first().json.body ?? $input.first().json;

// Required fields
const required = ['vorname','nachname','geburtsdatum','strasse','plz','ort','email','kategorie','beginn','kontoinhaber','iban','sepa_consent','privacy_consent'];
const missing = required.filter(k => !body[k]);
if (missing.length) {
  return [{ json: { ok: false, error: 'missing fields: ' + missing.join(', ') } }];
}

// IBAN Mod-97 sanity check
const iban = String(body.iban).replace(/\s+/g,'').toUpperCase();
const rearr = iban.slice(4) + iban.slice(0,4);
const numStr = rearr.replace(/[A-Z]/g, c => (c.charCodeAt(0) - 55).toString());
let rem = 0;
for (const d of numStr) { rem = (rem * 10 + Number(d)) % 97; }
if (rem !== 1) {
  return [{ json: { ok: false, error: 'invalid IBAN' } }];
}

// Mandatsreferenz
const nowIso = new Date().toISOString();
const mandateRef = 'TCBW-' + nowIso.replace(/[-:T.Z]/g,'').slice(0,12) + '-' + (body.nachname || '').slice(0,8).replace(/[^A-Za-z]/g,'').toUpperCase();

// Markdown email body for vorstand
const md = [
  '# Neuer Mitgliedsantrag',
  '',
  '**Eingegangen:** ' + nowIso,
  '**Mandatsreferenz:** ' + mandateRef,
  '**User-Agent:** ' + (body.user_agent || '–'),
  '',
  '## Persönliche Daten',
  '| Feld | Wert |',
  '|------|------|',
  '| Vorname | ' + body.vorname + ' |',
  '| Nachname | ' + body.nachname + ' |',
  '| Geburtsdatum | ' + body.geburtsdatum + ' |',
  '| Adresse | ' + body.strasse + ', ' + body.plz + ' ' + body.ort + ' |',
  '| E-Mail | ' + body.email + ' |',
  '| Telefon | ' + (body.telefon || '–') + ' |',
  '',
  body.guardian_name ? '## Erziehungsberechtigte/r\n| Name | ' + body.guardian_name + ' |\n| Telefon | ' + (body.guardian_telefon || '–') + ' |\n' : '',
  '## Mitgliedschaft',
  '| Feld | Wert |',
  '|------|------|',
  '| Kategorie | ' + body.kategorie + ' |',
  '| Beginn | ' + body.beginn + ' |',
  '',
  '## SEPA-Lastschriftmandat',
  '| Feld | Wert |',
  '|------|------|',
  '| Kontoinhaber:in | ' + body.kontoinhaber + ' |',
  '| IBAN | ' + iban + ' |',
  '| Mandat akzeptiert | ' + body.sepa_consent + ' |',
  '| Datenschutz akzeptiert | ' + body.privacy_consent + ' |',
  ''
].join('\n');

return [{ json: { ok: true, body, mandateRef, md, iban } }];
